        '''excited''는 기분이 좋아서 들뜨거나 신난 상태를 말해. 목소리에서 설렘이 느껴지는 상황이지.',
        'e로 시작하는 7글자 단어, ''흥분한'' 느낌',
        '[]'
    ),
    (
