        'check up',
        '''check up on''은 누군가의 안부나 상황을 확인한다는 뜻이야. check in이나 follow up도 비슷한 의미로 쓸 수 있어.',
        'c___ u_ (2단어, 전화로 상황 확인할 때 쓰는 표현)',
        '["check up", "check in", "follow up"]'
