        'certain',
        '''certain''은 뭔가가 분명하거나 확실할 때 쓰는 표현이야. 의심스러운 상황에서 확신을 나타낼 때 사용해.',
        'cert(증명서) + ain, certificate(자격증)과 같은 어원',
        '[]'
    ),
    (
        89,
