        '''분명한, 확실한'' = d______

Something is ______ wrong here.
(뜻: 뭔가 분명히 잘못됐어)',
        '[]',
        'definitely',
        '''definitely''는 ''분명히, 확실히''라는 뜻으로 확신을 표현할 때 쓰는 부사야.',
        'd로 시작, ''명백히/분명히''라는 부사로도 쓰여',
