        'smells fishy',
        '''Something smells fishy''는 뭔가 수상하다는 뜻이야. 생선이 상하면 냄새가 나듯이, 상황이 의심스러울 때 쓰는 관용 표현이지.',
        's_____ f____ (2단어, 생선 비린내를 떠올려봐 🐟)',
